import assert from 'node:assert/strict';
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import os from 'node:os';
import * as THREE from 'three';
import {buildTool, disposeToolLibrary} from './src/rig/tools.js';
import {createGltfRigs} from './src/core/gltfRig.js';
import {createRigSystem} from './src/rig/rigFactory.js';
import {clamp} from './src/core/contract.js';
import {RIGS} from './src/game/data.js';
import {blenderRigIds} from './tools/checkrigloader.mjs';
import {parseGLB, measure} from './tools/glbinfo.mjs';
const START = performance.now();
const current = readFileSync('src/core/preview.js', 'utf8');
const baseline = execFileSync('git', ['show', 'HEAD:src/core/preview.js'], {encoding:'utf8'});
const head = execFileSync('git', ['rev-parse','HEAD'],{encoding:'utf8'}).trim();
const sha = text => createHash('sha256').update(text).digest('hex');
function extract(source, start, end) {
 const a=source.indexOf(start), b=source.indexOf(end,a);
 assert.ok(a>=0&&b>a,'Exact function source boundaries must exist');
 return source.slice(a,b).trim();
}
const oldFrame = extract(baseline, '  function frame(', '\n  function build(');
const newFrame = extract(current, '  function frame(', '\n  function build(');
const support = extract(current, '  function sweepSupport(', '\n  /** Fit actual geometry');
const constants = current.match(/^const (?:FRAME_FILL|LIVE_PITCH) = .*;$/gm).join('\n');
function compile(source, extra='') {
 // Production function bodies below are verbatim, not translated algorithms.
 // Only their closure dependencies are supplied; timing wraps the call itself.
 const make = new Function('THREE_','clamp', constants+'\n'+
  'let camera = new THREE_.PerspectiveCamera(30,1,.05,60);\n'+
  'let backdrop = new THREE_.Object3D(); let lastFrame=null;\n'+
  extra+'\n'+source+'\nreturn {frame,camera,get lastFrame(){return lastFrame;}};');
 return make(THREE,clamp);
}
const old = compile(oldFrame), candidate=compile(newFrame,support);
const saved={warn:console.warn,info:console.info,error:console.error};
const diagnostics=[];
for(const level of Object.keys(saved)) console[level]=(...a)=>diagnostics.push({level,text:a.map(String).join(' ')});
const mats=new Map();
const ctx={THREE,quality:{id:'low'},qs:new URLSearchParams('glb=strict'),data:{RIGS},
 state:{garage:{rigId:'crawler-lite'},settings:{}},scene:new THREE.Scene(),
 assets:{material(kind,params={}){const key=kind+JSON.stringify(params);
 if(!mats.has(key)){const m=new THREE.MeshStandardMaterial(params);m.name=kind;mats.set(key,m);}
 return mats.get(key);}}};
globalThis.document={baseURI:'http://cpu-frame.invalid/'};
globalThis.fetch=async input=>{
 const u=new URL(input), match=/^\/models\/([a-z0-9-]+)\.glb$/.exec(u.pathname);
 assert.equal(u.origin,'http://cpu-frame.invalid');assert.ok(match);
 const buf=readFileSync('public/models/'+match[1]+'.glb');
 return {ok:true,arrayBuffer:async()=>buf.buffer.slice(buf.byteOffset,buf.byteOffset+buf.byteLength)};
};
const gltf=ctx.gltfRigs=createGltfRigs(ctx), ids=blenderRigIds();
for(const id of ids){
 const b=readFileSync('public/models/'+id+'.glb'),g=parseGLB(b),m=measure(g.json,g.bin);
 assert.ok(!m.empty&&!m.unreadable.length);
 await gltf.load(id);
}
const rig=ctx.rig=createRigSystem(ctx);
const tools=['button-bit','button-bit-t45','dth-bit','rc-bit','core-bit','pdc-bit',
 'tricone-bit','drill-rod','rod-r32','drill-collar','drill-pipe','push-rod','sda-bar',
 'cfa-flight','core-barrel','rc-dual-wall-pipe','jumbo-feed','tube-pile','precast-pile',
 'sheet-pile-pair','cable-bolt','bop-stack','rotary-drive-head','compressor-skid',
 'rc-cyclone','mesh-sheet','bolt-nut'];
const WARM=8, SAMPLES=48, rows=[];
function stats(a){
 const s=a.slice().sort((a,b)=>a-b);
 return {n:s.length,minMs:s[0],medianMs:(s[s.length/2-1]+s[s.length/2])/2,
 p95Ms:s[Math.ceil(s.length*.95)-1],maxMs:s.at(-1),meanMs:s.reduce((a,b)=>a+b,0)/s.length};
}
const corpus=tools.map(id=>({id,family:'tool'})).concat(ids.map(id=>({id,family:'rig'})));
try {
 for(let itemIndex=0;itemIndex<corpus.length;itemIndex++){
  const {id,family}=corpus[itemIndex];
  const group=family==='rig'?rig.buildPreview(id):buildTool(THREE,ctx,id,{wear:0,preview:true});
  assert.ok(group);
  if(family==='rig')assert.equal(group.userData.spec.source,'glb');
  let vertices=0,meshes=0;
  group.traverseVisible(o=>{if(o.geometry?.attributes?.position){meshes++;vertices+=o.geometry.attributes.position.count*(o.isInstancedMesh?o.count:1);}});
  const parent=new THREE.Group();parent.add(group);
  const modes=[
   {key:'baselineStatic',api:old,yaw:-.5,live:false},
   {key:'candidateStatic',api:candidate,yaw:-.5,live:false},
   {key:'baselineLive',api:old,yaw:0,live:false},
   {key:'candidateLive',api:candidate,yaw:0,live:true}
  ];
  const samples=Object.fromEntries(modes.map(m=>[m.key,[]]));
  const cold={};
  for(let round=-1;round<WARM+SAMPLES;round++){
   // Rotating Latin order avoids consistently measuring either side first.
   for(let step=0;step<modes.length;step++){
    const mode=modes[(step+Math.max(round,0)+itemIndex)%modes.length];
    parent.rotation.set(0,mode.yaw,0);
    const start=performance.now();
    mode.api.frame(group,mode.api.camera,mode.live);
    const ms=performance.now()-start;
    assert.ok(mode.api.lastFrame?.ok,id+' '+mode.key+' must actually frame');
    if(round===-1)cold[mode.key]=ms;
    if(round>=WARM)samples[mode.key].push(ms);
   }
  }
  const measured=Object.fromEntries(Object.entries(samples).map(([k,v])=>[k,stats(v)]));
  rows.push({id,family,vertices,meshes,firstCallMs:cold,...measured,
   staticMedianDeltaMs:measured.candidateStatic.medianMs-measured.baselineStatic.medianMs,
   liveMedianDeltaMs:measured.candidateLive.medianMs-measured.baselineLive.medianMs,
   samplesMs:samples});
  group.userData.dispose();
  saved.info('CPU frame '+(itemIndex+1)+'/'+corpus.length+' '+id+
   ': static '+measured.baselineStatic.medianMs.toFixed(3)+' -> '+measured.candidateStatic.medianMs.toFixed(3)+
   ' ms; live '+measured.baselineLive.medianMs.toFixed(3)+' -> '+measured.candidateLive.medianMs.toFixed(3)+' ms');
 }
 const sorted=(family,key)=>rows.filter(r=>r.family===family).map(r=>r[key].medianMs).sort((a,b)=>a-b);
 const aggregate={};
 for(const family of ['tool','rig']){
  const list=rows.filter(r=>r.family===family);aggregate[family]={count:list.length};
  for(const key of ['baselineStatic','candidateStatic','baselineLive','candidateLive']){
   const s=sorted(family,key);
   aggregate[family][key]={medianOfItemMediansMs:s[Math.floor(s.length/2)],worstItemMedianMs:s.at(-1),
    worstP95Ms:Math.max(...list.map(r=>r[key].p95Ms))};
  }
 }
 const updates=current.slice(current.indexOf('    update(dt) {'),current.indexOf('\n    resize()',current.indexOf('    update(dt) {')));
 const result={schema:1,measuredAt:new Date().toISOString(),baselineHead:head,
 machine:{platform:process.platform,arch:process.arch,node:process.version,logicalProcessors:os.cpus().length,
 cpuModels:[...new Set(os.cpus().map(c=>c.model))],totalMemoryBytes:os.totalmem()},
 source:{baselineSha256:sha(baseline),candidateSha256:sha(current),baselineFrameSha256:sha(oldFrame),
 candidateFrameSha256:sha(newFrame),sweepSupportSha256:sha(support)},
 protocol:{warmRounds:WARM,samplesPerMode:SAMPLES,modes:['baselineStatic','candidateStatic','baselineLive','candidateLive'],
 order:'Four-condition rotating Latin order per round and item; common already-built group; geometry/bounds warmed; no explicit GC.',
 geometry:'27 actual tools at wear0, plus all19 runtime-loaded GLBs through glbinfo validation and real gltfRig/rigFactory buildPreview.',
 timing:'performance.now around verbatim extracted production frame() function calls only. Closure supplies exact production camera initialization, backdrop scale target, and imported clamp. Builds, GLB loads, parent yaw changes, assertions, and rendering are outside timed intervals.',
 staticPose:{yaw:-.5,pitch:0},liveInitialPose:{yaw:0,pitch:0},candidateLive:'Full yaw and ±0.12 pitch support computed by verbatim sweepSupport(). Original had no separate live envelope.',
 caveats:['Shared Windows desktop CPU; other tasks may contend and clock speed/thermal state are uncontrolled.',
 'Node V8 CPU microbenchmark, not browser end-to-end latency, GPU timing, mobile timing, or FPS.',
 'Repeated framing is intentional solely for samples. Ordinary preview update does not frame; source replacement does.',
 'First-call timings are order-dependent diagnostics, not a controlled cold-start comparison.',
 'Warm old Box3 path benefits from cached geometry boxes exactly as already-built previews do. Allocation and any incidental GC during candidate frame remain included.']},
 ordinaryUpdateFrameCalls:updates.split('\n').filter(l=>/\bframe\(/.test(l)).map(l=>l.trim()),
 aggregate,elapsedMs:performance.now()-START,diagnostics,rows};
 writeFileSync('research/tool-preview-cpu-cost.json',JSON.stringify(result,null,2)+'\n');
 saved.info(JSON.stringify({aggregate,elapsedMs:result.elapsedMs,source:result.source},null,2));
} finally {rig.dispose();gltf.dispose();disposeToolLibrary();for(const m of mats.values())m.dispose();}
